import React, {useState} from 'react'
import {View,Image,StyleSheet,Text, Pressable} from 'react-native'

const Outdoor_CLG = ({route},{navigation}) => {

    const [rowGap, setrowGap] = useState(10);
    const [colGap, setcolGap] = useState(10);

    return(
    <PreviewLayout
        colGap = {colGap}
        handleColGapChange = {setcolGap}
        rowGap = {rowGap}
        handleRowGapChange = {setrowGap}> 

        <View style = {styles.container}>
            <View style = {styles.navbuttoncontainer}>
            <Text style = {{color: 'white', fontsize: 50}}>
                Which Sport?
            </Text>
            </View>
            <View style = {styles.orangebutton}>
                <Text style = {{color: 'black', fontsize: 40}}>
                    College: Indoor
                </Text>
            </View>
        </View>
        <View>
            <Pressable>
                <Image 
                    style = {styles.appdim}
                    source={require('/assets/basketBallGame.png')}/>
            </Pressable>
        </View>
        
    </PreviewLayout>

    );
    };

    const styles = StyleSheet.create({
        container:{
            flex: 1,
            backgroundColor: 'black'
        },
        navbuttoncontainer:{
        
            justifyContent: "top",
            alignItems:"center",
            height:50
        },
        navbutton:{
            height: 100,
            width: 200,
            borderWidth: 20,
            backgroundImage: 'linear-gradient(to right, #3437eb, #eb34d9)',
            justifyContent: "center",
            alignItems:"center"
           
        },
        orangebutton:{
            
            justifyContent: "flex-start",
            alignItems: "center",
            width: 200,
            height: 100,
            borderRadius: 100,
            borderWidth: 20,
            backgroundImage: 'linear-gradient(to right, #ffde59, #ff914d)',
            

        },
        appdim:{
            height : 300,
            width: 200
        },

     });
    
     export default Outdoor_CLG
